// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(0, "", ""); }
    function testRegression_property() public {
        address owner = address(this);
        c.mintToken(owner, 100);
        c.burn(1);
        uint256 balance = c.balanceOf(owner);
        assertTrue(balance < 100, "balance should be less than 100 after burn");
    }
}
